insert into public.gift_ideas (id, title, slug, summary, description, why_it_is_thoughtful, keywords, main_image_path, image_alt, external_url, source_name, is_featured, status, published_at, created_at) values ('0c480bad-f9f1-56a5-bd89-ba62204aa359', 'Recipe book filled by both families', 'family-recipe-book', 'A blank recipe book with favourite dishes written in by relatives from both sides.', 'Pass a hardcover recipe book around both families before the wedding and ask each person to write one recipe they love, with a note to the couple. Start early: this one takes a few weeks.', 'It brings two families'' kitchens together on the same pages.', 'recipe, cookbook, family, handwritten, food', '/images/gifts/family-recipe-book.jpg', 'Open recipe notebook with handwritten pages and family photos next to a bowl of spices', null, null, true, 'published', now() - interval '4 days', now() - interval '4 days') on conflict (id) do nothing;
