insert into public.gift_ideas (id, title, slug, summary, description, why_it_is_thoughtful, keywords, main_image_path, image_alt, external_url, source_name, is_featured, status, published_at, created_at) values ('686071f0-6ec1-5b3b-86da-70e733b95269', 'Pair of handmade ceramic mugs', 'handmade-ceramic-mugs', 'Two wheel-thrown mugs from a local potter, a little different from each other.', 'Handmade mugs are never quite identical, which makes a pair feel right for a couple. Check that the glaze is food-safe and dishwasher-safe if they''ll want that.', 'A small, everyday object that reminds them of the day each morning.', 'mugs, ceramic, pottery, coffee, tea, handmade', '/images/gifts/handmade-ceramic-mugs.jpg', 'Two handmade mugs, one coral and one sage green, with steaming coffee on a linen tablecloth', null, null, false, 'published', now() - interval '15 days', now() - interval '15 days') on conflict (id) do nothing;
