insert into public.gift_ideas (id, title, slug, summary, description, why_it_is_thoughtful, keywords, main_image_path, image_alt, external_url, source_name, is_featured, status, published_at, created_at) values ('8a9f93ec-95fd-5f35-8f85-53655fce59e0', 'Framed calligraphy of their names', 'name-calligraphy-frame', 'Their names written by a calligrapher in Bangla, English or Arabic script, framed.', 'A calligrapher can write the couple''s names, a date or a short blessing in the script that means most to them. Ask for an archival paper and a frame that suits their walls.', 'Handwritten names feel personal in a way printed ones don''t.', 'calligraphy, names, frame, art, bangla, arabic', '/images/gifts/name-calligraphy-frame.jpg', 'Framed black and gold brush calligraphy artwork on a cream wall above a console table', null, null, false, 'published', now() - interval '13 days', now() - interval '13 days') on conflict (id) do nothing;
