insert into public.gift_ideas (id, title, slug, summary, description, why_it_is_thoughtful, keywords, main_image_path, image_alt, external_url, source_name, is_featured, status, published_at, created_at) values ('cd57a5cc-de4a-53f0-9ef5-fce9122a639a', 'Silver-plated frame for a wedding photo', 'photo-frame-for-first-dance', 'An elegant frame ready for their favourite photo from the day.', 'Give the frame now and let the couple choose the photo later. A classic silver-plated or brass frame suits most homes; include a small card saying it''s waiting for a wedding picture.', 'It leaves room for the memory they''ll want to keep most.', 'photo frame, silver, picture, wedding photo', '/images/gifts/photo-frame-for-first-dance.jpg', 'Ornate silver photo frame on a cream dresser beside white roses and a satin ribbon', null, null, false, 'published', now() - interval '16 days', now() - interval '16 days') on conflict (id) do nothing;
