insert into public.gift_ideas (id, title, slug, summary, description, why_it_is_thoughtful, keywords, main_image_path, image_alt, external_url, source_name, is_featured, status, published_at, created_at) values ('4234756a-cf45-5dde-aa44-58f551967db4', 'Velvet-lined jewellery box for the bride', 'bridal-jewellery-box', 'A sturdy, lined box to keep wedding jewellery safe and organised.', 'Wedding jewellery is often given by both families and needs a safe home. Look for a box with soft lining, separate ring and earring sections and a lock or secure clasp.', 'It protects pieces that are often family heirlooms.', 'jewellery, jewelry box, bride, storage, velvet', '/images/gifts/bridal-jewellery-box.jpg', 'Lavender velvet jewellery box holding gold bangles, jhumka earrings and a ring', null, null, false, 'published', now() - interval '18 days', now() - interval '18 days') on conflict (id) do nothing;
